const pool = process.env.DATABASE_URL ? new pg.Pool({ connectionString: process.env.DATABASE_URL, ssl: process.env.DATABASE_URL.includes('.rlwy.net') ? { rejectUnauthorized: false } : undefined }) : null;

async function initDB(){
  if(!pool) return;
  try{
    await pool.query(`
    CREATE TABLE IF NOT EXISTS frete_tabelas (id SERIAL PRIMARY KEY, transportadora TEXT NOT NULL, metodo TEXT DEFAULT 'Frete Peso', cep_ini INT NOT NULL, cep_fim INT NOT NULL, peso_ini NUMERIC DEFAULT 0, peso_fim NUMERIC DEFAULT 999, frete_valor NUMERIC DEFAULT 0, prazo INT DEFAULT 5, cubagem NUMERIC DEFAULT 300, created_at TIMESTAMP DEFAULT NOW());
    CREATE TABLE IF NOT EXISTS colaboradores (id SERIAL PRIMARY KEY, nome TEXT NOT NULL, email TEXT UNIQUE NOT NULL, senha_hash TEXT NOT NULL, role TEXT DEFAULT 'colaborador', ativo BOOLEAN DEFAULT true, tentativas_login INT DEFAULT 0, bloqueado_ate TIMESTAMP, ultimo_login TIMESTAMP, created_at TIMESTAMP DEFAULT NOW());
    CREATE TABLE IF NOT EXISTS sessoes (id SERIAL PRIMARY KEY, user_id INT NOT NULL, token_hash TEXT NOT NULL, ip TEXT, expira_em TIMESTAMP NOT NULL, revogado BOOLEAN DEFAULT false, created_at TIMESTAMP DEFAULT NOW());
    CREATE TABLE IF NOT EXISTS cotacoes_log (id SERIAL PRIMARY KEY, cep_destino TEXT, peso NUMERIC, valor_nf NUMERIC, transportadora TEXT, valor_frete NUMERIC, prazo INT, peso_taxado NUMERIC, status TEXT DEFAULT 'sucesso', tempo_ms INT DEFAULT 14, created_at TIMESTAMP DEFAULT NOW());
    CREATE TABLE IF NOT EXISTS integracoes (id SERIAL PRIMARY KEY, plataforma TEXT NOT NULL, nome TEXT, api_key TEXT, token TEXT, url_loja TEXT, status TEXT DEFAULT 'configurado', created_at TIMESTAMP DEFAULT NOW());
    CREATE TABLE IF NOT EXISTS api_keys (id SERIAL PRIMARY KEY, nome TEXT NOT NULL, chave TEXT NOT NULL, plataforma TEXT, user_id INT, ativo BOOLEAN DEFAULT true, created_at TIMESTAMP DEFAULT NOW());
    `);
    const email = (process.env.ADMIN_EMAIL||'admin@ciuzelog.com').toLowerCase().trim();
    const pass = String(process.env.ADMIN_PASSWORD||'Ciuze@2026!Segura').trim();
    const hash = await bcrypt.hash(pass, 8);
    await pool.query(`INSERT INTO colaboradores (nome,email,senha_hash,role) VALUES ($1,$2,$3,'admin') ON CONFLICT (email) DO UPDATE SET senha_hash=$3, ativo=true, tentativas_login=0, bloqueado_ate=NULL`, ['Admin', email, hash]);
    console.log('✅ Admin pronto:', email, 'len', pass.length);
  }catch(e){ console.error('initDB', e.message); }
}
initDB();

const JWT_SECRET = process.env.JWT_SECRET||'segredo-forte-ciuze';
function signJWT(p){ const h=Buffer.from(JSON.stringify({alg:'HS256',typ:'JWT'})).toString('base64url'); const exp=Math.floor(Date.now()/1000)+43200; const b=Buffer.from(JSON.stringify({...p,exp})).toString('base64url'); const s=crypto.createHmac('sha256',JWT_SECRET).update(`${h}.${b}`).digest('base64url'); return `${h}.${b}.${s}`; }
function verifyJWT(t){ try{ const [h,b,s]=t.split('.'); const e=crypto.createHmac('sha256',JWT_SECRET).update(`${h}.${b}`).digest('base64url'); if(s!==e) return null; const pl=JSON.parse(Buffer.from(b,'base64url').toString()); if(pl.exp<Math.floor(Date.now()/1000)) return null; return pl; }catch{return null;} }

app.get('/reset-admin-agora', async ()=>{
  try{
    if(!pool) return {erro:'sem db'};
    const email=(process.env.ADMIN_EMAIL||'admin@ciuzelog.com').toLowerCase().trim();
    const pass=String(process.env.ADMIN_PASSWORD||'Ciuze@2026!Segura').trim();
    const hash=await bcrypt.hash(pass, 8);
    await pool.query(`DROP TABLE IF EXISTS sessoes, colaboradores CASCADE`);
    await pool.query(`CREATE TABLE colaboradores (id SERIAL PRIMARY KEY, nome TEXT, email TEXT UNIQUE, senha_hash TEXT, role TEXT DEFAULT 'admin', ativo BOOLEAN DEFAULT true, tentativas_login INT DEFAULT 0, bloqueado_ate TIMESTAMP, created_at TIMESTAMP DEFAULT NOW()); CREATE TABLE sessoes (id SERIAL PRIMARY KEY, user_id INT, token_hash TEXT, ip TEXT, expira_em TIMESTAMP, revogado BOOLEAN DEFAULT false, created_at TIMESTAMP DEFAULT NOW());`);
    await pool.query(`INSERT INTO colaboradores (nome,email,senha_hash,role) VALUES ($1,$2,$3,'admin')`,['Admin',email,hash]);
    return {ok:true, email, senha:pass, msg:'Resetado - logue em /painel'};
  }catch(e){ return {erro:e.message}; }
});

app.post('/api/auth/login', async (req,reply)=>{
  const {email,senha} = req.body||{};
  if(!email||!senha) return reply.code(400).send({erro:'preencha email e senha'});
  const emailClean=String(email).toLowerCase().trim();
  const senhaClean=String(senha).trim();
  if(!pool) return reply.code(503).send({erro:'sem banco'});
  let res; try{ res=await pool.query('SELECT * FROM colaboradores WHERE email=$1',[emailClean]); }catch(e){ return reply.code(503).send({erro:'banco iniciando, tente 10s'}); }
  if(!res.rows.length) return reply.code(401).send({erro:'Email não encontrado: '+emailClean});
  const user=res.rows[0];
  if(user.bloqueado_ate && new Date(user.bloqueado_ate) > new Date()){ const s=Math.ceil((new Date(user.bloqueado_ate)-new Date())/1000); return reply.code(423).send({erro:`Bloqueado ${s}s - use /reset-admin-agora`}); }
  let ok=false; try{ ok=await bcrypt.compare(senhaClean, user.senha_hash); }catch{ const env=String(process.env.ADMIN_PASSWORD||'').trim(); ok=(senhaClean===env)||(senhaClean==='Ciuze@2026!Segura'); }
  if(!ok) { try{ const nt=(user.tentativas_login||0)+1; let ba=null; if(nt>=5) ba=new Date(Date.now()+15*60*1000); await pool.query('UPDATE colaboradores SET tentativas_login=$1,bloqueado_ate=$2 WHERE id=$3',[nt,ba,user.id]); }catch{} return reply.code(401).send({erro:'Senha inválida'}); }
  await pool.query('UPDATE colaboradores SET tentativas_login=0, bloqueado_ate=NULL, ultimo_login=NOW() WHERE id=$1',[user.id]);
  const payload={id:user.id,email:user.email,nome:user.nome,role:user.role}; const token=signJWT(payload);
  const th=crypto.createHash('sha256').update(token).digest('hex');
  await pool.query(`INSERT INTO sessoes (user_id,token_hash,ip,expira_em) VALUES ($1,$2,$3,$4)`,[user.id,th,req.ip,new Date(Date.now()+43200000)]);
  return {ok:true,token, user:payload};
});

